flags = {s for e in j["flag"] for s in ([e] if isinstance(e,str) else e)}
opts  = {s for e in j["option"] for s in e[:-1]}
def parse(words):
    fo, ops, i = [], [], 0
    while i < len(words):
        w = words[i]
        if w in flags: fo.append(w)
        elif w in opts: fo.append((w, words[i+1])); i += 1
